catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    g_form.setMandatory('comments', false);
    var now = new Date();
    var desireddate = new Date(getDateFromFormat(g_form.getValue("select_the_desired_date"), g_user_date_time_format));
    var returndate = new Date(getDateFromFormat(g_form.getValue('return_date'), g_user_date_time_format));
    if (returndate < desireddate) {
        g_form.addErrorMessage("Veuillez noter que la date de retour doit être après la date désirée.");
        g_form.clearValue('return_date');
    }
    var new24 = desireddate.setHours(desireddate.getHours() + 24);
    if (returndate > new24) {

        g_form.setMandatory('comments', true);
    }
	var desireddate = g_form.getValue('select_the_desired_date');

    if (newValue > desireddate ) {
        var ga = new GlideAjax('EnergirComputerEquipment');
        ga.addParam('sysparm_name', 'Computerequipmentloan');
        ga.addParam('sysparm_desireddate', desireddate);
        ga.addParam('sysparm_returndate', newValue);
        ga.getXML(generateResponse);

        function generateResponse(response) {
            var newOptions = JSON.parse(response.responseXML.documentElement.getAttribute("answer"));
            if (newOptions && Array.isArray(newOptions)) {
                // Supprimer toutes les options existantes
                g_form.clearOptions('list_of_available_equipment');
                g_form.addOption('list_of_available_equipment', '', '-- Aucun --');
                // Ajouter les nouvelles options disponibles
                for (var i = 0; i < newOptions.length; i++) {
                    g_form.addOption('list_of_available_equipment', newOptions[i], newOptions[i]);
                }
                g_form.addInfoMessage('Prenez note que si l\'équipement n\'est pas dans la liste, c\'est qu\'il n\'est pas disponible à la date que vous avez choisie.');
            } else {
                g_form.addInfoMessage('Aucune option disponible pour la date sélectionnée.');
            }
        }


    }



}
